solucion.sqlserver:
SELECT IdPedido, FechaPedido, IDCliente, IDEmpleado
FROM Pedidos
WHERE YEAR(FechaPedido) = 2020 AND MONTH(FechaPedido) = 6;

SELECT IDPedido, FechaPedido, IDCliente, IDEmpleado
FROM Pedidos
WHERE DAY(FechaPedido) = DAY(EOMONTH(FechaPedido));

SELECT IDPedido, FechaPedido, IDCliente, IDEmpleado
FROM Pedidos
WHERE DAY(FechaPedido) = DAY(EOMONTH(FechaPedido))-1;

SELECT IDEmpleado, Nombre, Apellido
FROM Empleados
WHERE Apellido LIKE '%e%e%';

SELECT IDEmpleado, Apellido
FROM Empleados
WHERE Apellido COLLATE Latin1_General_CS_AS LIKE N'[abcdefghijklmnopqrstuvwxyz]%';

exercises.enunciado:
Explique la diferencia entre las siguientes consultas:
-- Consulta 1
SELECT IDEmpleado, COUNT(*) AS numordenes FROM Pedidos WHERE FechaPedido < '20220501' GROUP BY IDEmpleado;
-- Consulta 2
SELECT IDEmpleado, COUNT(*) AS numordenes FROM Pedidos GROUP BY IDEmpleado HAVING MAX(FechaPedido) < '20220501';

